using System.Net;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly HttpListener listener = new();
    private readonly HttpClient client;
    private readonly string baseUrl;
    private Task<CapturedRequest>? captured;

    public HttpPaymentGatewayTests()
    {
        var port = GetFreePort();
        baseUrl = $"http://127.0.0.1:{port}/";
        listener.Prefixes.Add(baseUrl);
        listener.Start();
        client = new HttpClient { BaseAddress = new Uri(baseUrl) };
    }

    private sealed record CapturedRequest(string Method, string Path, string? ContentType, string Body);

    private static int GetFreePort()
    {
        var l = new System.Net.Sockets.TcpListener(IPAddress.Loopback, 0);
        l.Start();
        var port = ((IPEndPoint)l.LocalEndpoint).Port;
        l.Stop();
        return port;
    }

    private void Respond(int status, string? body, string contentType = "application/json")
    {
        captured = Task.Run(async () =>
        {
            var ctx = await listener.GetContextAsync();
            using var reader = new StreamReader(ctx.Request.InputStream, Encoding.UTF8);
            var requestBody = await reader.ReadToEndAsync();
            var snapshot = new CapturedRequest(ctx.Request.HttpMethod, ctx.Request.Url!.AbsolutePath, ctx.Request.ContentType, requestBody);

            ctx.Response.StatusCode = status;
            if (body is not null)
            {
                var bytes = Encoding.UTF8.GetBytes(body);
                ctx.Response.ContentType = contentType;
                ctx.Response.ContentLength64 = bytes.Length;
                await ctx.Response.OutputStream.WriteAsync(bytes);
            }
            ctx.Response.Close();
            return snapshot;
        });
    }

    private Task<AuthorizationOutcome> Authorize(string reference = "ORD-7", decimal amount = 12.50m, string currency = "eur") =>
        new HttpPaymentGateway(client).AuthorizeAsync(reference, new Money(amount, currency), CancellationToken.None);

    [Fact]
    public async Task Sends_a_json_post_to_the_authorizations_endpoint_with_reference_amount_and_currency()
    {
        Respond(200, """{"status":"approved"}""");

        await Authorize("ORD-7", 12.50m, "eur");

        var request = await captured!;
        Assert.Equal("POST", request.Method);
        Assert.Equal("/v1/authorizations", request.Path);
        Assert.StartsWith("application/json", request.ContentType);
        using var doc = JsonDocument.Parse(request.Body);
        var root = doc.RootElement;
        Assert.Equal(["amount", "currency", "reference"], root.EnumerateObject().Select(p => p.Name).Order().ToArray());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(JsonValueKind.Number, root.GetProperty("amount").ValueKind);
        Assert.Equal(12.50m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        Respond(200, """{"status":"approved"}""");

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        Respond(200, """{"status":"declined"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        Respond(200, """{"id":"auth_1","status":"approved","risk":{"score":3}}""");

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_402_refusal_is_a_decline_even_with_an_error_body()
    {
        Respond(402, """{"error":"card_refused"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task A_402_refusal_without_a_body_is_a_decline()
    {
        Respond(402, null);

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData("""{"status":"pending"}""")]
    [InlineData("""{"status":"APPROVED"}""")]
    [InlineData("""{"state":"approved"}""")]
    [InlineData("""{"status":null}""")]
    [InlineData("null")]
    public async Task An_answer_that_is_not_exactly_approved_is_never_treated_as_approved(string body)
    {
        Respond(200, body);

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task A_malformed_answer_is_an_error_not_an_approval()
    {
        Respond(200, "<html>oops</html>");

        await Assert.ThrowsAnyAsync<JsonException>(Authorize);
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Any_other_failure_status_surfaces_as_an_error_rather_than_a_decision(int status)
    {
        Respond(status, """{"status":"approved"}""");

        var error = await Assert.ThrowsAsync<HttpRequestException>(Authorize);
        Assert.Equal((HttpStatusCode)status, error.StatusCode);
    }

    public void Dispose()
    {
        client.Dispose();
        listener.Close();
    }
}
